<?php
require_once __DIR__ . '/../../includes/bootstrap.php';
require_once __DIR__ . '/../../includes/database.php';
require_once __DIR__ . '/../../includes/layout.php';
require_login();
$mode=$_GET['mode']??'daily'; $date=$_GET['date']??date('Y-m-d'); $month=$_GET['month']??date('Y-m');
if ($mode==='monthly') { $st=db()->prepare("SELECT e.employee_no, SUM(a.status IN ('PRESENT','LATE','EARLY_OUT')) P, SUM(a.status='LATE') L, SUM(a.status='ABSENT') A, SUM(a.status='EARLY_OUT') E FROM employees e LEFT JOIN attendance_daily a ON a.employee_id=e.id AND DATE_FORMAT(a.work_date,'%Y-%m')=? WHERE e.status='active' GROUP BY e.id ORDER BY e.employee_no"); $st->execute([$month]); $rows=$st->fetchAll(); }
elseif ($mode==='history') { $q=trim($_GET['q']??'25-0001'); $st=db()->prepare("SELECT work_date,time_in,time_out,status,late_minutes,early_out_minutes FROM attendance_daily a JOIN employees e ON e.id=a.employee_id WHERE e.employee_no=? ORDER BY work_date DESC LIMIT 100"); $st->execute([$q]); $rows=$st->fetchAll(); }
else { $mode='daily'; $st=db()->prepare("SELECT e.employee_no, CONCAT(e.first_name,' ',e.last_name) nm, d.department_code, a.time_in, a.time_out, a.status, a.late_minutes, a.early_out_minutes FROM employees e LEFT JOIN attendance_daily a ON a.employee_id=e.id AND a.work_date=? LEFT JOIN departments d ON d.id=e.department_id WHERE e.status='active' ORDER BY e.employee_no"); $st->execute([$date]); $rows=$st->fetchAll(); }
$headers = $mode==='monthly' ? ['employee_no','P','L','A','E'] : ($mode==='history' ? ['work_date','time_in','time_out','status','late_minutes','early_out_minutes'] : ['employee_no','nm','department_code','time_in','time_out','status','late_minutes','early_out_minutes']);
?>
<?php layout_start('Reports','reports'); ?>
<div class="page-intro"><div><p class="eyebrow">Insights</p><h2>Attendance insights</h2><p>Compare attendance by day or month, or review one employee’s history.</p></div></div>
<div class="card table-card"><div class="table-toolbar"><div><h3><?=e(ucfirst($mode))?> report</h3><p><?=count($rows)?> results</p></div><form method="get" class="filter-form noprint"><label class="sr-only" for="report-mode">Report type</label><select id="report-mode" name="mode" onchange="reportFields()"><option value="daily" <?=$mode==='daily'?'selected':''?>>Daily</option><option value="monthly" <?=$mode==='monthly'?'selected':''?>>Monthly</option><option value="history" <?=$mode==='history'?'selected':''?>>Employee history</option></select><label class="sr-only" for="report-date">Date</label><input id="report-date" data-report="daily" type="date" name="date" value="<?=e($date)?>"><label class="sr-only" for="report-month">Month</label><input id="report-month" data-report="monthly" type="month" name="month" value="<?=e($month)?>"><label class="sr-only" for="report-employee">Employee number</label><input id="report-employee" data-report="history" name="q" placeholder="Employee number" value="<?=e($_GET['q'] ?? '')?>"><button>View</button><button type="button" onclick="window.print()">Print</button></form></div><div class="tw"><table><thead><tr><?php foreach($headers as $h): ?><th><?=e(['nm'=>'Name','P'=>'Present','L'=>'Late','A'=>'Absent','E'=>'Early out'][$h]??ucwords(str_replace('_',' ',$h)))?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php foreach($r as $h=>$v): ?><td><?=in_array($h,["status"])?badge((string)$v):e((string)$v)?></td><?php endforeach; ?></tr><?php endforeach; if(!$rows): ?><tr><td class="empty" colspan="<?=count($headers)?>">No report data for this selection.</td></tr><?php endif; ?></tbody></table></div></div><script>function reportFields(){var mode=document.getElementById('report-mode').value;document.querySelectorAll('[data-report]').forEach(function(el){el.hidden=el.dataset.report!==mode;el.disabled=el.hidden})}reportFields()</script><?php layout_end(); ?>
